    traffic.spawnCrowdAround(x, z, cars, (cx, cz, r) => {
      peds.spawnCrowdAround(cx, cz, pedsCount, r);
    }, radius);
    peds.spawnCrowdAround(x, z, pedsCount, radius);
  }

  return api;
}

